def test_cursor_row_text_joins_split_spans_but_ignores_the_left_column():
    from docich.hanjuku_speedrun.hanjuku.flows.battle_menus import _cursor_row_text
    from docich.hanjuku_speedrun.hanjuku_font import TextLine
    from docich.hanjuku_speedrun.hanjuku_screen import Screen

    split = Screen([TextLine(176, ((176, 'こう'), (200, 'げき')))], None, 'こうげき')
    split.menu_rows = list(split.lines)
